#!/usr/bin/env node

/**
 * РЎРєСЂРёРїС‚ РґР»СЏ СЃРѕР·РґР°РЅРёСЏ Р±СЌРєР°РїР° PostgreSQL Р±Р°Р·С‹ РґР°РЅРЅС‹С…
 * РСЃРїРѕР»СЊР·РѕРІР°РЅРёРµ: npm run backup
 */

import { exec } from 'child_process';
import { promisify } from 'util';
import * as fs from 'fs';
import * as path from 'path';

const execAsync = promisify(exec);

// РљРѕРЅС„РёРіСѓСЂР°С†РёСЏ
const BACKUP_DIR = path.join(process.cwd(), 'backups');
const MAX_BACKUPS = 7; // РҐСЂР°РЅРёС‚СЊ РїРѕСЃР»РµРґРЅРёРµ 7 Р±СЌРєР°РїРѕРІ

/**
 * РџР°СЂСЃРёРЅРі DATABASE_URL
 */
function parseDatabaseUrl(url: string) {
  const regex = /postgresql:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/;
  const match = url.match(regex);

  if (!match) {
    throw new Error('РќРµРІРµСЂРЅС‹Р№ С„РѕСЂРјР°С‚ DATABASE_URL');
  }

  return {
    user: match[1],
    password: match[2],
    host: match[3],
    port: match[4],
    database: match[5].split('?')[0], // РЈР±РёСЂР°РµРј query РїР°СЂР°РјРµС‚СЂС‹
  };
}

/**
 * РЎРѕР·РґР°РЅРёРµ РґРёСЂРµРєС‚РѕСЂРёРё РґР»СЏ Р±СЌРєР°РїРѕРІ
 */
function ensureBackupDir() {
  if (!fs.existsSync(BACKUP_DIR)) {
    fs.mkdirSync(BACKUP_DIR, { recursive: true });
    console.log(`рџ“Ѓ РЎРѕР·РґР°РЅР° РґРёСЂРµРєС‚РѕСЂРёСЏ РґР»СЏ Р±СЌРєР°РїРѕРІ: ${BACKUP_DIR}`);
  }
}

/**
 * РЎРѕР·РґР°РЅРёРµ Р±СЌРєР°РїР°
 */
async function createBackup() {
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    throw new Error('DATABASE_URL РЅРµ РЅР°Р№РґРµРЅ РІ РїРµСЂРµРјРµРЅРЅС‹С… РѕРєСЂСѓР¶РµРЅРёСЏ');
  }

  const db = parseDatabaseUrl(databaseUrl);
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-').split('T')[0];
  const backupFile = path.join(BACKUP_DIR, `mm05_backup_${timestamp}.sql`);

  console.log('рџ”„ РЎРѕР·РґР°РЅРёРµ Р±СЌРєР°РїР° Р±Р°Р·С‹ РґР°РЅРЅС‹С…...');
  console.log(`рџ“¦ Р‘Р°Р·Р°: ${db.database}`);
  console.log(`рџЏ  РҐРѕСЃС‚: ${db.host}`);

  // РљРѕРјР°РЅРґР° pg_dump
  const command = `PGPASSWORD="${db.password}" pg_dump -h ${db.host} -p ${db.port} -U ${db.user} -d ${db.database} -F p -f "${backupFile}"`;

  try {
    await execAsync(command);
    console.log(`вњ… Р‘СЌРєР°Рї СЃРѕР·РґР°РЅ: ${backupFile}`);
    
    // РџРѕР»СѓС‡Р°РµРј СЂР°Р·РјРµСЂ С„Р°Р№Р»Р°
    const stats = fs.statSync(backupFile);
    const fileSizeMB = (stats.size / (1024 * 1024)).toFixed(2);
    console.log(`рџ“Љ Р Р°Р·РјРµСЂ: ${fileSizeMB} MB`);

    return backupFile;
  } catch (error: any) {
    console.error('вќЊ РћС€РёР±РєР° СЃРѕР·РґР°РЅРёСЏ Р±СЌРєР°РїР°:', error.message);
    throw error;
  }
}

/**
 * РЈРґР°Р»РµРЅРёРµ СЃС‚Р°СЂС‹С… Р±СЌРєР°РїРѕРІ
 */
function cleanOldBackups() {
  const files = fs.readdirSync(BACKUP_DIR)
    .filter(file => file.startsWith('mm05_backup_') && file.endsWith('.sql'))
    .map(file => ({
      name: file,
      path: path.join(BACKUP_DIR, file),
      time: fs.statSync(path.join(BACKUP_DIR, file)).mtime.getTime(),
    }))
    .sort((a, b) => b.time - a.time);

  if (files.length > MAX_BACKUPS) {
    const toDelete = files.slice(MAX_BACKUPS);
    console.log(`рџ—‘пёЏ  РЈРґР°Р»РµРЅРёРµ СЃС‚Р°СЂС‹С… Р±СЌРєР°РїРѕРІ (РѕСЃС‚Р°РІР»СЏРµРј ${MAX_BACKUPS} РїРѕСЃР»РµРґРЅРёС…)...`);

    toDelete.forEach(file => {
      fs.unlinkSync(file.path);
      console.log(`   РЈРґР°Р»РµРЅ: ${file.name}`);
    });
  }
}

/**
 * Р“Р»Р°РІРЅР°СЏ С„СѓРЅРєС†РёСЏ
 */
async function main() {
  console.log('\nрџ”ђ MM05 Database Backup Tool\n');
  console.log('в•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ\n');

  try {
    ensureBackupDir();
    await createBackup();
    cleanOldBackups();

    console.log('\nв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ');
    console.log('вњ… Р‘СЌРєР°Рї СѓСЃРїРµС€РЅРѕ СЃРѕР·РґР°РЅ!');
    console.log(`рџ“Ѓ Р”РёСЂРµРєС‚РѕСЂРёСЏ: ${BACKUP_DIR}`);
    console.log('в•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ\n');
  } catch (error: any) {
    console.error('\nвќЊ РћС€РёР±РєР°:', error.message);
    process.exit(1);
  }
}

main();

